      "（2）工作经历：曾经在山东省冠县人民医院、国家卫健委科学技术研究所、天津和睦家医院从事泌尿外科、男科工作。",
      "（3）进修经历：曾经在山东大学齐鲁医院、北京大学第一医院、北京大学第三医院进修泌尿外科、男科。",
