    "specialty": "男性不育症的诊断与治疗，生育力的评估：包括男性不育症、疑难少弱畸精子症、无精子症等；男科疾病的诊断、治疗：包括勃起功能障碍、早泄、前列腺疾病、生殖器疾病等；男性生殖内分泌疾病的诊断、治疗：例如性腺功能减退症及其评估及治疗等；男性计划生育的咨询与手术：直视钳穿法输精管结扎术等；男科手术：包括显微输精管附睾吻合术、睾丸/附睾穿刺取精术、生殖器整形等。"
