    "specialty": "面部、乳房及形体美容外科、皮肤软组织肿瘤治疗与修复、头面部及四肢畸形与组织缺损的修复； 以创伤、畸形修复和美容外科工作为重点，在复杂创伤、畸形显微外科修复和面部美容外科方面积累了丰富的经验，形成了较为突出的医疗特色。"
