  "1106": {
    "bio": [
      "第四军医大学学士、硕士，军事医学科学院博士、博士后，原中国人民解放军空军总医院放疗科副主任医师。发表国际SCI期刊论文19篇，中文核心期刊论文26篇，参编了《肿瘤放射外科治疗学》等7部著作。"
    ],
    "appointments": [
      "CSCO（中国临床肿瘤学会）食管癌专家委员会委员",
      "IASLC（国际肺癌研究学会）会员",
      "北京精准放射医学学会理事",
      "北京精准放射医学学会放射外科分会委员",
      "北京医学会肿瘤放射治疗委员会食管癌学组委员",
      "北京癌症防治学会呼吸道肿瘤药物不良反应管理专委会委员"
    ],
    "honors": [],
    "specialty": "对多数常见肿瘤（如肺癌、食管癌、胸腺瘤、肝癌、乳腺癌、宫颈癌、直肠癌、胰腺癌、前列腺癌、脑转移瘤、骨转移瘤等）具有丰富的放射治疗和综合治疗经验，尤其擅长肺癌的放疗、化疗、靶向治疗、免疫治疗等综合治疗模式。创新性地实践以现代精准放射治疗理念为指导、高分次剂量放疗为特点的肿瘤综合治疗新模式，对早期肿瘤实施高剂量放射外科杀灭治疗，对中、晚期肿瘤实施全身选择性放疗+靶向药物/化疗等综合治疗的新策略。紧紧围绕以患者为中心，个体化地为每位患者制定最佳的治疗策略。"
  },
