  "1089": {
    "bio": [
      "李雪盛，医学博士，博士后，北京大学国际医院耳鼻咽喉头颈外科副主任医师。北京市自然科学基金评审专家，中国医师协会耳鼻咽喉头颈外科学分会鼻科学组委员。2013年-2015年先后在澳大利亚阿德莱德大学伊丽莎白皇后医院、奥地利格拉茨医科大学耳鼻咽喉头颈外科医院访问研修鼻内镜微创外科技术。先后主持完成各类课题4项，发表SCI论文2篇，核心期刊统计源期刊论文45篇，获得实用新型专利1项，参编专著6部，获得军队科技进步2等奖一项，河北医疗成果三等奖1项。"
    ],
    "appointments": [
      "北京医学会耳鼻咽喉头颈外科学分会委员；",
      "中国装备学会耳鼻咽喉头颈外科学分会委员；",
      "中国老年保健医学研究会耳鼻咽喉科学分会委员",
      "8-11届中华医学会耳鼻咽喉头颈外科学分会青年委员；",
      "11届中华耳鼻咽喉头颈外科学杂志编委会鼻科组委员；",
      "《中华耳鼻咽喉头颈外科杂志》通讯编委；",
      "《中国耳鼻咽喉颅底外科杂志》编委；",
      "《中国耳鼻咽喉头颈外科》编委；",
      "《医学参考报耳鼻咽喉头颈外科频道》常务编委；",
      "《当代医学》常务编委。"
    ],
    "honors": [],
    "specialty": "耳鼻喉科常见病及疑难病诊断与治疗。在鼻内窥镜微创手术治疗各型鼻窦炎、变应性鼻炎、鼻外伤、鼻腔鼻窦肿瘤、脑脊液鼻漏、腺样体肥大、慢性泪囊炎、视神经减压、眼眶减压等方面经验丰富。"
  },
  "948": {
    "bio": [
      "北京大学国际医院中医科副主任。本科毕业于北京中医药大学，北京大学医学部硕士研究生，师从北京大学人民医院呼吸科高占成教授。北京大学第一医院、岐黄学者、北京市名中医张学智教授第六批北京市级中医药专家学术经验继承人。在北大核心期刊发表多篇文章，理论研究方向为从寒热论治内科疾病，善于针药并用治疗消化系统及妇科系统等复杂性疾病。"
    ],
    "appointments": [
      "中华预防医学会中西医结合预防与保健分会委员",
      "中华中医药学会综合医院中医药工作委员会委员",
      "中西医结合学会针药并用专业委员会委员",
      "中国中医药研究促进会消化整合医学分会常务理事",
      "北京中医药学会临床药学专业委员会常务委员",
      "北京医师协会中西医结合肿瘤专业委员会委员"
    ],
    "honors": [],
    "specialty": "中西医结合治疗消化系统疾病（慢性胃炎、幽门螺杆菌感染、胃食管反流、慢性腹泻、便秘、功能性消化不良慢性萎缩性胃炎等）。妇科疾病（月经不调、卵巢早衰、多囊卵巢综合征、带下病、产后病）及肿瘤辅助治疗，肿瘤放化疗期扶正治疗，主要研究方向为寒热平调、针药并用治疗慢性疾病（肥胖相关性代谢类疾病、失眠、焦虑、面神经麻痹、产后恢复、亚健康状态及肿瘤放化疗综合征的整体调节）。"
  },
