  "1201": {
    "bio": [
      "北京大学国际医院心理行为医学科副主任。心理学硕士、精神科副主任医师、健康管理师，北京市女医师协会健康管理学分会委员。曾历任北京市体检中心体检科副科长，北京小汤山医院保健办副主任，健康管理中心办公室主任，北京市卫生和计划生育委员会保健办副主任科员，北京大学国际医院健康管理中心筹备组成员，特需医疗部住院体检病房筹备组成员。擅长焦虑障碍，抑郁障碍，睡眠障碍，躯体疾病伴发的心理问题，健康管理方案制定，健康咨询。曾以第一作者发表《乌灵胶囊联合西药治疗脑卒中抑郁患者临床疗效及对患者血清炎症因子和NPY的影响》、《产妇身心健康水平、家庭环境和地域习俗对产妇产后抑郁发生的影响》等论文数篇。"
    ],
    "appointments": [
      "中国女医师协会精神卫生专业委员会委员",
      "北京整合医学学会心理行为医学专委会副主任委员",
      "中国心理卫生协会会员"
    ],
    "honors": [],
    "specialty": "1、精神科常见疾病：擅长各类焦虑障碍，抑郁障碍，睡眠障碍，双相情感障碍等精神科常见疾病的诊断、结合心理治疗与药物干预的个体化精准治疗。 2、儿童青少年心理行为干预：擅长青少年情绪障碍，厌学拒学、多动障碍，抽动障碍，学习困难心理咨询与治疗 3、压力管理：擅长职场压力管理与心理调适，运用正念减压，认知行为调整等适宜技术进行心理咨询与治疗。 4、心身疾病：擅长原发性高血压、胃肠功能紊乱，神经性尿频、不明原因疼痛、恶性肿瘤等心身疾病症状改善、躯体疾病伴发的心理问题咨询与治疗； 5、女性心理：擅长女性备孕期、围产期、经期、围绝经期心理咨询与治疗； 6、创伤治疗：擅长危机干预、重大生活事件引起的心理、情绪障碍治疗，以EMDR创伤治疗进行改善 7、擅长婚姻、家庭、情感、亲子关系等方面心理咨询与治疗。长期接受系统式心理治疗、EMDR创伤治疗、正念治疗、儿童青少年心理治疗的专业培训，并进行临床实践。"
  },
