  "1394": {
    "bio": [
      "刘双，主任医师，教授，博士生导师，北京大学国际医院特聘教授。曾任首都医科大学附属北京安贞医院呼吸与危重症医学科主任，首都医科大学危重症学系副主任。从事呼吸与危重症医学临床、科研和教学工作30余年，在呼吸系统常见病多发病以及疑难病方面积累了丰富的临床经验，主要研究方向为肺栓塞与肺血管疾病；气道疾病；肺部感染及呼吸危重症。发表学术论文上百篇，主编《SARS临床病例及影像学分析》，参编《中老年与呼吸系统疾病》、《肺栓塞--多学科病例分析》、《肺栓塞诊疗手册》，主译《急诊气道管理》、《重症监护学》等著作。"
    ],
    "appointments": [
      "中国医师协会呼吸分会肺栓塞与肺血管病工作组成员；",
      "北京医学会呼吸病学分会常委；",
      "中国老年医学呼吸病学分会委员；",
      "中国女医师协会呼吸专委会常委；",
      "《中华结核和呼吸杂志》、《心肺血管病杂志》、《中华全科医学杂志》等编委。"
    ],
    "honors": [],
    "specialty": "肺栓塞、肺动脉高压等肺血管疾病、复杂性呼吸系统感染"
  },
