      "中国医药生物技术协会心血管外科技术与工程分会常委",
      "中华志愿者协会中西医结合专家志愿者委员会胸外科专业组常委",
      "全国卫生产业企业管理协会 肿瘤预防与治疗康复分会肿瘤专家智库峰会副主席",
      "海峡两岸医药卫生交流协会国际医疗与特需服务专委会委员",
