    "specialty": "心力衰竭、高血压、血脂代谢异常、冠心病心肌梗塞、心肌病、早搏、房颤、高尿酸血症、高同型半胱氨酸血症、糖尿病、甲状腺功能亢进/减低、功能医学、健康管理、体重管理、女性更年期综合征以及严重冠脉疾病的诊断和药物治疗。"
