  "1277": {
    "bio": [
      "主任医师、副教授，硕士生导师。1990年毕业于北京医科大学医疗系，1998年在北京大学医学部(原北京医科大学)获博士学位，导师陈清棠教授。2006年赴德国乌尔姆大学做为访问学者学习神经免疫。",
      "临床工作：熟练掌握神经系统疾病的诊断和治疗，尤其对神经免疫学疾病(包括多发性硬化症、重症肌无力、多发性肌炎、AIDP和CIDP等)有深入的临床和应用基础研究。所负责的神经免疫室能开展血液及脑脊液的多种免疫学检查，包括辅助诊断重症肌无力的抗AChR、Titin、RyR抗体、辅助诊断炎性肌肉病的肌炎特异性抗体、辅助诊断副肿瘤综合征的抗Hu、Yo、Ri抗体、辅助诊断周围神经病的神经节苷酯抗体谱以及辅助诊断中枢神经系统炎性疾病和多发性硬化症的寡克隆区带和髓鞘蛋白抗体、AQP4(NMO-IgG)抗体、自身免疫脑炎的NMDA抗体等。周三上午参加全科大查房，主要诊断和治疗神经内科的疑难杂症。",
      "教学工作：参加北京大学神经内科的教学工作，负责神经内科进修医师的临床和教学培训，到目前，独立指导培养硕士生8名，做为博士生副导师辅助指导培养博士生3名。 科研工作：做为主要项目成员，参加过脑血管疾病八五、九五重大攻关课题的部分工作，参加过国家自然基金和卫生部课题基金等课题工作，其中原发性线粒体肌病与脑肌病的诊断与治疗的科研课题，曾获卫生部科研成果奖1项、北京市成果奖1项。到目前以第一作者或通讯作者身份在主要期刊发表论文23余篇，以主要完成者身份参与发表论文30余篇，参加编写专著3部。中国免疫学会神经免疫分会委员、中华医学会老年医学分会神经学组委员、中国卒中学会神经免疫分会委员、北京神经内科学会神经感染与免疫专业委员会委员"
    ],
    "appointments": [
      "现任中国免疫学会神经免疫分会委员、中华医学会老年医学分会神经学组委员、北京神经内科学会神经感染与免疫专业委员会委员等。"
    ],
    "honors": [],
    "specialty": "神经系统疾病的诊断及治疗，包括神经免疫学疾病(如多发性硬化症、重症肌无力、多发性肌炎、AIDP和CIDP等)。"
  },
  "97699": {
    "bio": [
      "毕业于天津医科大学，现在海淀区妇幼保健院乳腺科及北京大学国际医院乳腺科从事知名专家门诊及部分手术工作。曾在北京大学人民医院、北京大学肿瘤医院、天津肿瘤医院乳腺外科进修学习两年。"
    ],
    "appointments": [
      "现为国际认证泌乳顾问（IBCLC）、中国红十字会爱婴医院发展基金母乳喂养专家组组长、北京围手术期医学学会腔镜专委会常委等。曾主持中国康复医学会、中国红十字会爱婴医院发展基金多中心课题；参加多项省部级课题项目；以第一作者发表三篇SCI论文；一作在《中华医学杂志》《中国妇产科临床杂志》等核心期刊发表近20篇论文。人民卫生出版社《产后康复指南》《母乳喂养理论与实践》、《基层卫生人员培训教程与实践指导-婴幼儿喂养咨询》副主编及主要作者。"
    ],
    "honors": [],
    "specialty": "国际认证泌乳顾问11年（IBCLC），擅长哺乳期和非哺乳期各种炎症；乳腺结节乳腺癌早期诊断和治疗；母乳喂养。"
  },
