      "中国医学救援协会运动伤害分会理事，关节运动伤害学组常务委员；",
      "中国研究型医院协会骨科创新转化专业委员会运动损伤学组委员；",
      "中国研究型医院协会关节外科专业委员会社区关节疾病防治研究学组委员；",
