  "1257": {
    "bio": [
      "徐新保，医学博士，副主任医师。从事肝胆外科、普通外科、内镜及介入治疗工作30余年，曾经在陆军军医大学第一附属医院（西南医院）、解放军空军总医院、北京大学人民医院等国内著名大型三甲医院工作。熟练开展肝胆外科及普通外科常规手术、胃肠镜技术、ERCP技术、肝胆胰肿瘤的血管介入技术，开展了超声引导下肝脏肿瘤消融技术、胆囊及胆管穿刺引流技术。曾经从事肝脏移植临床工作，并有肝脏移植相关的临床文章发表，经过正规肝移植培训，获得了国家卫健委承认的肝移植医师资质。率先开始针对空军飞行员胆囊结石、胆囊息肉患者施行微创保胆手术，治疗效果满意，后将该技术推广至其他军人及地方患者，总计为军地患者施行微创保胆手术2000余例。"
    ],
    "appointments": [
      "陆军军医大学外科博士，北京大学外科博士后，中华医学会及中国医师协会会员，曾任北京健康促进会肝胆胰专家委员会委员、国家肿瘤微创治疗技术创新联盟﹣普通外科专业委员会委员等。",
      "获得军队医疗成果二等奖4项，军队医疗成果三等奖1项，发表论文40余篇。"
    ],
    "honors": [],
    "specialty": "肝胆外科常规及复杂手术、ERCP技术、胃肠镜检查及治疗、肿瘤的血管介入及消融技术、微创保胆手术、肝脏移植术。"
  },
