  "3188": {
    "bio": [
      "2004-2007年在北京大学泌尿外科研究所攻读医学博士学位，2008年5月在美国加州大学旧金山分校（UCSF）医学中心参加“将才工程”培训，2008年9月在捷克布拉格参加欧洲泌尿外科住院医师教育项目（EUREP）培训。 2010年获得全国青年泌尿外科医师技能大赛第一名，曾先后代表中华医学会泌尿外科学分会前往美国、法国、德国、意大利、捷克等国家对外交流访。2012年由中华医学会泌尿外科分会选派在梅奥医学中心（Mayo Clinic）参访。",
      "完成国家自然科学基金青年项目一项，主持和参与国自然基金项目多项，主持多项北京市科委、北京市卫计委及北京大学医学部课题。在国内外核心期刊发表专著20余篇，并参与《坎贝尔泌尿外科学》、《泌尿外科临床操作》、《泌尿外科病例精编》等医学著作的翻译和编写工作。"
    ],
    "appointments": [
      "中国临床肿瘤学会前列腺癌专家委员会委员",
      "中国性学会男性生殖医学分会委员",
      "中国健康促进委员会北京泌尿外科分会青年委员",
      "中国老年学和老年医学学会老年泌尿和肾病分会委员",
      "北京医师协会泌尿外科分会理事",
      "北京尿控学会青年委员",
      "北京市抗癌协会泌尿肿瘤青委会委员"
    ],
    "honors": [],
    "specialty": "男性勃起功能障碍和早泄的诊断和治疗，阴茎疾病，前列腺疾病，生殖系肿瘤，尿控及压力性尿失禁疾病，复杂泌尿系结石、肾脏和膀胱肿瘤的微创手术和治疗。在复杂生殖系肿瘤手术和前列腺癌保留性神经手术方面积累了丰富经验。擅长泌外及男科微创成型手术：阴茎假体植入，阴茎增粗延长、腹腔镜输尿管成型手术、输尿管狭窄球囊扩张术、前列腺球囊扩裂术、肾盂输尿管连接部狭窄内切开术等。"
  },
