    "specialty": "擅长癫痫（FCD、海绵状血管瘤、低级别胶质瘤、结节性硬化等）的外科治疗。 颅内病变的磁共振引导下激光热凝消融（LITT）治疗。 昏迷、植物状态、意识障碍术前评估及功能神经外科治疗。 各种疼痛，如面肌痉挛、三叉神经痛的微血管减压治疗、三叉神经痛微创治疗 脑梗塞后肢体偏瘫、脑脊髓损伤后肌张力障碍、脊髓损伤体位性低血压的神经调控治疗、难治性抑郁症的神经调控。 脑机接口调控治疗"
