    "specialty": "擅长各种内外科急危重症疾病如重症感染、各类型休克、多脏器功能衰竭、危重孕产妇救治、严重创伤、严重颅脑疾病及颅脑损伤等危重症疾病的救治，尤其对体外生命支持技术 - 体外膜肺氧合（ ECMO ）的运行及管理有丰富经验。"
