  "1338": {
    "bio": [
      "王慧颖，副主任医师，疼痛科主任助理。从事疼痛诊疗工作20余年，具备坚实的理论基础及丰富的临床经验。掌握了超声引导下病灶精准注射治疗，再生疗法（富血小板血浆PRP治疗），神经阻滞治疗，射频调控、等离子、臭氧、电刺激、鞘内泵植入术、黄帝内针等治疗方法。擅长各种急慢性疼痛包括偏头痛，紧张型头痛，颈源性头痛，三叉神经痛，颈肩腰腿痛，关节疼痛，带状疱疹后遗痛，神经损伤等神经痛，网球肘、腱鞘炎、筋膜炎等软组织疼痛，癌性疼痛等疾病的诊断、鉴别诊断和个体化治疗。曾负责国家临床重点专科建设项目一疼痛平台建设子课题的研究；参加首都卫生发展科研专项项目和北京市科学技术委员会批准项目课题的研究。参译著作2部。"
    ],
    "appointments": [
      "国际疼痛研究协会（IASP）会员",
      "北京慢病防治与健康教育研究会疼痛可视化综合管理专委会 常务委员",
      "中国指挥与控制学会医工结合专业委员会 常务委员",
      "北京医师协会疼痛专科医师分会 理事",
      "中国超声医学工程学会麻醉与疼痛超声专委会 委员",
      "中国女医师协会疼痛专委会 委员",
      "北京围手术期医学研究会麻醉与疼痛专委会 委员",
      "北京中西医结合学会麻醉与镇痛专委会 青年委员",
      "北京整合医学学会疼痛学分会 委员",
      "中国非公立医疗机构协会疼痛专委会 委员",
      "北京中西医结合协会环境与健康专委会 委员"
    ],
    "honors": [],
    "specialty": "慢性疼痛及难治性疼痛的个体化诊断及有创精准治疗。 超声引导下病灶精准注射治疗，再生疗法（富血小板血浆PRP治疗），神经阻滞治疗，射频消融、射频神经调控、低温等离子射频、臭氧、电刺激、吗啡泵植入等微创手术，联合药物治疗、物理治疗、针灸治疗等方式综合治疗难治性疼痛。尤其擅长全面考虑患者情况制定个体化方案、精准的治疗头面部疼痛，颈、胸、腰背痛，肢体疼痛，肩、肘、腕、髋、膝、踝、手足等关节疼痛，腱鞘炎、网球肘、肌筋膜炎等软组织疼痛，带状疱疹、三叉神经、肋间神经、神经感觉异常、神经损伤等神经痛，癌性疼痛，顽固性失眠，雷诺氏综合征，术后疼痛等。"
  },
