  "97826": {
    "bio": [
      "现任职于中国中医科学院西苑医院综合科副主任医师、执业中药师，中国中医科学院中西医结合临床硕士，兼任中国药膳研究会理事。",
      "先后拜师于中国中医科学院首届中青年名中医、全国首届名中医，潜心研习脾胃学说与中西医结合诊疗体系，恪守“脾胃为后天之本”学术理念，推崇从脾胃入手调治百病。深耕中医经典，熟练运用传统中医经典理论指导临床，临床功底扎实，熟练掌握各类常见病、多发病的辨证论治。从事中西医结合临床工作十余载，融合传统中医辨证思维与现代医学诊疗手段，重视身心同调、药食同源；善于处理多种慢病共存、病机复杂的疑难病症，遵循个体化诊疗思路，用药平和，兼顾汤药治疗与药膳调养。对待患者耐心细致，在消化疾病、过敏性呼吸系统病症、情志睡眠障碍、内分泌失调、亚健康康复等领域积累丰厚临床经验，收获众多患者好评。",
      "长期扎根临床一线，深耕中医药科研、学术传承与大众健康科普领域，成果丰硕。科研学术方面，先后参与省部级、院级中医药科研课题4项，作为主要起草人之一起草中华中医药学会行业标准1项；累计在国内外专业期刊、主流报刊发表学术及科普文章70余篇，主编专著3部、副主编1部、参编专著7部。曾获中国药膳研究会首届药膳大会·2021中国药膳学术研讨会优秀论文二等奖。"
    ],
    "appointments": [
      "中国中医科学院西苑医院综合科副主任医师",
      "中华中医药学会中医康复技术传承创新平台常务委员",
      "中国药膳研究会理事",
      "获中国药膳研究会首届药膳大会·2021中国药膳学术研讨会优秀论文二等奖"
    ],
    "honors": [],
    "specialty": "一、脾胃病（消化系统疾病）调理 专攻慢性胃炎、萎缩性胃炎、胃溃疡、消化不良、反流性食管炎、慢性结肠炎、腹胀、腹泻、便秘等消化系统病症。中医认为此类病症多与脾胃运化失司、气机升降失常、湿浊内蕴相关，脾虚证、脾虚湿蕴证、痰湿证为本病常见核心证型。通过健脾和胃、消疡护膜、理气化滞、化湿和中、润肠通腑等治法，搭配个性化方药，既能缓解胃痛反酸、腹胀便溏、大便秘结等不适，又能顾护脾胃本源，恢复中焦运化平衡，从根源调护胃肠机能。 二、肺系病（呼吸系统疾病）调理 针对急性咳嗽、慢性咳嗽、过敏性咳嗽、过敏性鼻炎、过敏性哮喘、慢性阻塞性肺疾病稳定期等肺系疾患。中医认为该类疾患常责之于肺气宣降失常、肺气不足、肺经郁热、肺热痰盛。采用宣肺肃降、祛风脱敏、清肺泻热、化痰平喘、补肺固卫等治法，个体化配伍方药，改善咳嗽、咽痒喘息、鼻塞鼻痒、气短痰多等症状，扶助肺气，调和肺脏机能，改善过敏体质，减少病症反复。 三、心系病（心血管系统疾病）调理 调治心悸、胸闷、胸痛、气短、失眠多梦等心系相关病症，多因心气不足、心阳不足、心血不足，脏腑气血阴阳失和所致。遵循益气温阳、养血宁心、理气宽胸、安神定志治法，运用经方、时方辨证组方，缓解心慌憋闷、气短乏力、夜寐不安等表现，调和心之气血阴阳，改善心神状态。 四、常见杂病与术后康复调理 涵盖自汗、盗汗、梅核气、脱发、腰腿痛、急躁焦虑、更年期综合征、慢性疲劳综合征、免疫力低下等各类内科杂病及癌症术后调理。本类病症常见肝郁证、气虚证、阳虚证、阴虚证、脾肾亏虚证、心脾两虚证、肺肾亏虚证、肝肾不足证等病机。癌症术后多存在正气耗伤、余邪未尽之态，以扶正固本为要；杂病注重整体辨证，疏肝调气、益气温阳、滋阴固本、补益脾肾肝肾，兼顾祛邪，改善躯体不适与情绪状态，调补机体正气，提升身体机能，践行“未病先防、既病调愈”理念，改善生活质量。 五、术后康复专项调理 专注癌症、常规外科等各类手术术后的中医体质修复与康复调养。手术创伤及术中气血耗散，会致使机体元气受损、脏腑气机紊乱，残余病邪滞留体内，术后常表现为神疲乏力、精神倦怠、免疫机能下降、恢复进程迟缓，多伴随情绪郁结、身心失调等状态，若体虚日久不调，易造成外邪反复侵袭、旧疾复发。临证遵循培元固本、益气生血、养阴护正、健脾益肾、祛邪清余、调和脏腑的施治原则，结合不同术式、康复周期与个人体质辨证施治、定制方药。侧重补益虚损元气、修复受损脏腑功能、肃清体内残留邪毒，有效改善术后疲惫、体虚易感、情志焦虑等问题，筑牢机体抗病屏障，规避复发风险，促进全身机能有序恢复，帮助患者重塑健康体质，回归平稳身心状态与正常生活。"
  },
