  "98405": {
    "bio": [
      "中国中医科学院西苑医院针灸科副主任医师，中医学博士后。中国针灸学会委员，北京针灸学会委员。国家体育总局“中国冰雪医务专家”；主持并参与国家自然科学基金项目、国家“十一五”科技支撑计划项目、国家“十二五”科技支撑计划项目多项，获得国家专利一项，作为第一作者在国家科技核心期刊发表学术论文20余篇。担任《中医杂志》编委。"
    ],
    "appointments": [
      "中国中医科学院西苑医院针灸科副主任医师，中国针灸学会委员，北京针灸学会委员。国家体育总局“中国冰雪医务专家”；",
      "主持并参与国家自然科学基金项目、国家“十一五”科技支撑计划项目、国家“十二五”科技支撑计划项目多项，获得国家专利一项，作为第一作者在国家科技核心期刊发表学术论文20余篇。担任《中医杂志》编委。中国对外派出的全球首支国家级中医抗疫专家组--“国家援柬埔寨中医抗疫专家组”专家。2023年获得“柬埔寨王国骑士勋章”。受中联部邀请参加第三届“一带一路”国际合作高峰论坛。"
    ],
    "honors": [],
    "specialty": "1、五官科病症针灸调理 调理耳聋、耳鸣、中耳炎、近视、飞蚊症、干眼症、慢性鼻炎、慢性咽炎等五官科慢性病症。本病多由肾精不足、肝胆火旺、肺卫不固、风热上扰、经络瘀滞、窍络失养所致，虚实夹杂、反复发作。通过针刺益肾聪耳、清肝明目、宣肺通窍、利咽散结、通络开窍，疏通头面经络、濡养五官窍络，改善耳闷耳鸣、眼干视物模糊、鼻塞咽干等症，清解潜伏浊火、调理脏腑，缓解慢性炎症，减少复发。 2、放化疗后遗症针灸调理 专项针灸改善肿瘤患者放化疗后各类并发症。放化疗毒邪易耗伤元气、灼伤阴津、损伤脾胃、阻滞经络，多见咽痛声嘶、吞咽不利、神疲乏力、食欲差、恶心呕吐、腹泻便秘等症状。临证以针灸扶正固本、益气养阴、健脾和胃、解毒通络，通过针刺补泻培补元气、调和脾胃升降、肃清残留毒邪，改善放化疗后体虚、消化紊乱、咽喉不适，提升机体免疫力与耐受度，助力康复。 3、皮肤病症针灸调理 针灸调治痤疮、褐黄斑、湿疹、带状疱疹、荨麻疹等皮肤疾患。皮肤病多因风热蕴肤、湿热毒郁、肝郁血瘀、气血失和，邪毒外发肌肤所致。采用针刺疏风清热、利湿解毒、凉血散瘀、调和气血，局部与远端取穴相配，疏通皮下经络瘀堵、排泄湿浊瘀热，改善皮疹、瘙痒、疱疹、色斑等皮损，从脏腑本源调理体质，降低复发率。 4、妇科病症针灸调理 针灸调理卵巢低反应、反复种植失败、卵巢功能减退、不孕、月经不调、痛经、子宫内膜异位症、子宫腺肌症、慢性盆腔炎、压力性尿失禁等妇科病症。妇科诸疾多责之于肝肾亏虚、冲任失调、气血瘀滞、肝郁痰湿、下焦失固。通过针刺疏肝益肾、调理冲任、益气活血、温通胞脉、固摄下焦，调节内分泌与脏腑气血，疏通盆腔瘀滞、濡养卵巢胞宫，改善经期不适、盆腔炎症，优化生殖内环境，修复盆底机能。 5、神经系统病症针灸调理 针治面神经炎、头痛、面肌痉挛、三叉神经痛、中风后遗症、顽固性失眠等神经系统病症。本病多为风邪入络、痰瘀阻窍、气血不足、阴阳失调、心神失养所致。针灸可祛风通络、平肝息风、活血化瘀、宁心安神、调和阴阳，快速疏通经络、修复神经功能，改善面肌痉挛、神经痛、肢体麻木偏瘫，调节睡眠，促进中风后神经与肢体功能恢复。 6、消化系统病症针灸调理 针灸调理慢性胃炎、反流性食管炎、功能性消化不良、腹泻、便秘、小儿积食等消化病症。多因脾胃虚弱、肝气犯胃、气机阻滞、湿热蕴脾、升降失常引发。通过针刺健脾和胃、疏肝理气、消食导滞、调肠通腑，调节胃肠气机、改善蠕动紊乱，缓解胃胀反酸、纳差、腹痛、二便失常，修复脾胃运化功能，适配成人慢病调理与小儿积食调理。 7、颈肩腰腿痛及骨关节针灸调理 专治颈椎病、颈椎间盘突出、肩周炎、腰肌劳损、腰椎间盘突出、肌筋膜炎、膝关节炎、风湿性关节炎等骨关节痹症。痹症多由风寒湿侵袭、经络瘀阻、气血不畅、肝肾亏虚、筋骨失养导致关节疼痛、僵硬、麻木、活动受限。针刺可祛风除湿、散寒通络、活血舒筋、益肾强骨、行气止痛，松解肌群粘连、疏通经络瘀堵、改善筋骨血供，快速缓解各类颈肩腰腿痛，恢复关节机能，防止劳损反复。 8、针灸术后康复专项调理 运用针灸开展外科、骨科、脏腑、泌尿、肿瘤等各类术后康复调理。手术创伤耗伤元气、损伤经络、瘀滞气血，术后多见体虚乏力、多汗、创口愈合慢、肢体肿痛僵硬、粘连麻木、腹胀纳差等问题，易遗留功能障碍、体虚反复等后遗症。临证以针灸固本培元、益气生血、祛瘀通络、行气散结、健脾助运、肃清残邪为纲，结合手术部位、体质、恢复阶段辨证施针。可补益元气、疏通术后瘀滞、松解粘连、调和气血，加速创口与经络修复，改善术后虚弱、疼痛麻木，预防功能受限，提速整体机能康复。"
  },
