  "1448": {
    "bio": [
      "2007年毕业于同济大学获学士学位；2010年毕业于北京大学医学部获硕士学位，同年至北京大学首钢医院吴阶平泌尿外科医学中心工作，历任住院医师、主治医师、副主任医师，熟练掌握本专业疾病的诊断和治疗。",
      "2010-2013年于北京大学第三医院进行北京市住院医师规范化培训，并荣获“北京大学第三医院优秀住院医师”称号；",
      "2017年上海第二军医大学长海医院机器人手术精训班学习；",
      "2019年全国中青年泌尿外科医师临床科研技能大赛三等奖；",
      "北京大学2022北京冬奥会、冬残奥会医疗保障优秀个人；",
      "2022-2023年于301医院（解放军总医院）张旭院士团队进修学习腹腔镜及机器人手术；",
      "2023.07加入北京大学国际医院泌尿外科；",
      "2025年荣获“北京大学国际医院优秀医师”。"
    ],
    "appointments": [
      "北京整合医学会泌尿外科分会委员；",
      "中国非公立医院协会泌尿外科专业委员会委员；",
      "北京医学会泌尿外科分会尿控学组青年委员；",
      "北京市中西医结合学会男科委员会委员；",
      "北京市中西医结合学会盆底功能障碍专业委员会委员；",
      "北京健康促进会泌尿外科分会青年委员；",
      "中国性学会男性生殖医学分会委员；",
      "中欧泌尿外科联合培训项目腹腔镜操作培训专家；",
      "吴阶平医学基金会中国输尿管软镜培训项目专家。"
    ],
    "honors": [
      "北京大学2022北京冬奥会、冬残奥会医疗保障优秀个人；",
      "2019年全国中青年泌尿外科医师临床科研技能大赛三等奖；",
      "北京大学第三医院优秀住院医师；",
      "北京大学国际医院优秀医师。"
    ],
    "specialty": "1、 疑难复杂泌尿系统肿瘤、结石（包括前列腺癌、膀胱癌，肾上腺肿瘤、肾脏肿瘤、肾盂和输尿管肿瘤、肾输尿管结石等）的微创手术治疗（包括机器人辅助腹腔镜、腹腔镜、输尿管镜、经皮肾镜手术等）、快速康复治疗和个体化治疗，最大程度保留器官功能。独立完成和参与泌尿系统肿瘤、结石手术累积数千台。 2、 前列腺增生的微创手术治疗：曾成功完成多例疑难巨大体积前列腺的经尿道前列腺剜除术（其中1例体积超过300ml，3例体积在250-300ml，最高龄92岁，术后年龄逾100岁患者1例），让病人排尿回到童年时的畅快。 3、 尿控疾病（如压力性尿失禁等）尤其是女性泌尿外科疾病的诊断和治疗。"
  },
  "1145": {
    "bio": [
      "毕业于北京大学医学部，外科学博士学位。发表SCI论文多篇，参与国家自然科学基金3项，获发明专利1项，新型实用专利1项。"
    ],
    "appointments": [],
    "honors": [],
    "specialty": "髋、膝、肩、踝关节的退行性疾病与运动损伤的诊断与治疗，尤其在骨关节炎治疗,运动损伤治疗及人工关节置换术后功能康复方面具有独到见解。擅长膝关节骨关节炎，类风湿关节炎的人工膝关节置换；髋关节骨关节病，股骨颈骨折，股骨头缺血坏死的髋关节置换；人工关节置换术后并发症的治疗，包括人工关节松动，假体周围感染的治疗；关节镜下膝关节半月板撕裂修复，膝关节前、后交叉韧带断裂重建手术，复发性髌骨脱位的治疗；肩周炎治疗，肩袖撕裂治疗；踝关节扭伤的治疗。"
  },
  "1158": {
    "bio": [
      "2015年毕业于首都医科大学，目前主要研究方向为各关节疾病的诊断及治疗。"
    ],
    "appointments": [],
    "honors": [],
    "specialty": "骨关节疾病的诊治，包括膝、肩、肘、踝、腕运动损伤治疗，老年性骨关节疾病的诊疗。擅长人工髋关节置换术、膝关节置换术，膝关节软骨、半月板、韧带损伤及髌骨脱位的微创修复重建，膝关节腘窝囊肿切除，色素绒毛结节性滑膜炎清理。肩关节盂唇撕裂、复发脱位及肩袖撕裂的微创修复。踝关节韧带损伤、跟腱断裂的微创修复。腕关节运动损伤的微创治疗。"
  },
