      "毕业于北京协和医院，在阜外医院、协和医院及天坛医院外科病房进行严格的系统的外科医师专科培训，掌握各种心脏外科复杂疑难病例的诊断、治疗方案及手术操作技巧。赴美国克利夫兰医学中心及纽约州圣约瑟夫医院青年访问学者，获北京大学青年新星计划科研立项支持，入选北大国际医院菁英计划及国际医疗中心接诊医师。"
