    "specialty": "中西医结合治疗消化系统疾病（如幽门螺杆菌感染、胃食管反流、慢性胃炎、便秘、慢性腹泻、消化不良、消化道系统肿瘤等），擅长针灸药治疗神经系统疾病（如脑血管病、周围性面瘫等）、各种急慢性疼痛（如血管神经性头痛、颈椎病、肩周炎、腰肌劳损、腰椎间盘突出、痛风、产后腰痛、癌因性疼痛等），肿瘤术后及放化疗期间的中医协同治疗，慢性疾病如过敏性鼻炎、慢性咽炎、咳嗽、睡眠障碍、高血压、糖尿病、脂代谢异常，以及慢性疲劳等亚健康状态的中医调理。"
