  "1097": {
    "bio": [
      "2011年本科毕业于中山大学，2016年博士毕业于北京大学医学部口腔医学院（正颌外科学方向），师从我国著名正颌外科学专家王兴教授、李自力教授。2020年赴韩国首尔大学口腔医学院进修学习，汲取国际先进的数字化外科与面部整形理念。现任北京大学国际医院口腔颌面外科主任助理。长期从事口腔颌面外科临床、教学及科研工作，致力于为患者提供功能与美观并重的个性化诊疗方案。"
    ],
    "appointments": [
      "北京口腔医学会会口腔颌面外科专业委员会青年委员",
      "中华口腔医学会会员",
      "中华口腔医学会创伤及正颌委员会会员",
      "杂志《Sleep and Breath》审稿人"
    ],
    "honors": [
      "主持及参与科研项目4项，在国内外核心期刊发表学术论文5篇，参与译注书籍1本，参编专业著作2部。",
      "曾获北京大学医学部优秀住院医师称号，多次荣获医院“优秀员工”“优秀医师”等荣誉。"
    ],
    "specialty": "颌面外科全科： 各类阻生牙、颌骨囊肿、头颈部肿瘤等常见病的规范化治疗。 正畸-正颌联合治疗： 擅长矫正骨性“地包天”、突嘴、长脸及面部不对称，兼顾咬合功能与面部美学。 面部轮廓整形： 下颌角、颧骨、下巴等轮廓精细整形，致力于打造自然和谐的面部线条。 创伤与畸形修复： 颌面部骨折复位内固定、颅颌面先天及继发畸形的综合整复治疗。"
  },
