    "specialty": "体表肿物的美容手术治疗；面颈部年轻化及注射美容：水光、肉毒素、玻尿酸、胶原。皮肤抗衰：热玛吉、黄金微针、热拉提等射频。激光治疗：色素痣、光子嫩肤、美白紧致、皮肤粗糙老化、脱毛、敏感肌、痤疮、色斑（雀斑、黄褐斑、晒斑等）。眼整形（双眼皮、提眉、眼袋）、吸脂、脂肪填充、不明注射物取出、隆鼻、除皱及轮廓整形、植发；腋臭、男性乳房肥大、副乳的微创治疗。瘢痕、巨痣的系统治疗。创面修复（外伤、烧烫伤、褥疮、手术后伤口愈合不良、糖尿病足）。"
