  "97828": {
    "bio": [
      "中医学博士、博士后，中国中医科学院副研究员、主治医师、讲师，硕士研究生导师，全国中医药经典能力等级考试评阅专家，全国名老中医学术经验传承人。师从中国中医科学院首席研究员曹洪欣教授、全国名老中医药专家高彦彬教授，荣获北京代谢病防治研究贡献奖。 先后在中国中医科学院中医门诊部、首都医科大学国医名师馆、丰台区中医医院多点出诊，曾任大兴区中西医结合医院内分泌科会诊专家。 长期深耕中医经方理论的临床、科研与教学工作，立足传统中医药理论，善用中医经典名方开展辨证施治。主持国家自然科学基金课题5项，参与国家科技重大专项、国家重点研发等各类课题10余项；发表SCI等学术论文50余篇；出版学术专著7部，其中担任副主编4部、参编著作3部。 兼任中国中医药信息学会孙思邈研究分会常务理事、中华中医药学会仲景学说分会青年委员、中国代谢病创新联盟副秘书长、北京市慢病管理专业委员会副秘书长，拥有扎实深厚的中医药理论功底与丰富的临床实践经验。"
    ],
    "appointments": [
      "中国中医科学院门诊主治医师",
      "师从中国中医科学院首席研究员曹洪欣教授、全国名老中医药专家高彦彬教授，中医学博士，美国加州大学洛杉矶分校访问学者，荣获北京代谢病防治研究贡献奖",
      "中国中医药信息学会孙思邈研究分会常务理事",
      "中华中医药学会仲景学说分会青年委员",
      "中国代谢病创新联盟副秘书长",
      "北京市慢病管理专业委员会副秘书长"
    ],
    "honors": [],
    "specialty": "一、心脑血脉病症调理 专攻冠心病、心律失常、心脏神经官能症、头痛、眩晕头晕等心脑血脉类疾患。中医认为此类病症多与心脉痹阻、气血亏虚、气机失调、清窍失养、肝肾阴阳失衡相关。通过益气活血、通脉宁心、平肝息风、养血定眩等治法，搭配个性化方药，改善胸闷心悸、心慌失眠、头目胀痛眩晕等不适，调和气血血脉，安定心神，恢复脏腑阴阳平衡。 二、脾胃消化疾病调理 针对各类脾胃病、胆囊结石等消化系统疾患。本类疾病病机多责之于脾胃运化失司、肝胆疏泄失常、湿浊痰瘀蕴结中焦。以健脾和胃、疏肝利胆、理气消胀、化痰散结为主要治法，运用经方时方辨证配伍，缓解胃脘不适、胁肋胀痛、纳差腹胀等症状，调和肝胆脾胃机能，疏利肝胆气机。 三、妇科相关疾病调理 调治月经不调、子宫内膜异位症、更年期综合征等妇科病症。中医病机常见冲任失调、气滞血瘀、肝肾亏虚、阴阳失和。采用调理冲任、活血化瘀、补益肝肾、调和阴阳等治法，个体化配伍方药，改善经期紊乱、痛经癥瘕、烘热烦躁、情志波动等表现，调护胞宫，改善女性周身状态。 四、肾脏代谢疾病调理 专注各类肾病中医调理。此类疾患多为本虚标实，核心病机为脾肾亏虚，水湿、湿热、瘀浊内阻。通过益肾固元、健脾培土、利湿泄浊、活血通络等治法，顾护先后天之本，改善腰膝酸软、水肿、身体困重等相关症状，扶正祛邪，调固肾脏机能。 五、体质调养与治未病指导 擅长亚健康状态调理，提供中医养生、未病先防专业指导。多因脏腑失调、气血阴阳偏颇引发疲乏、情绪不畅、睡眠欠佳等各类不适。立足整体辨证，调补气血、平衡阴阳，纠正偏颇体质，践行治未病理念，帮助改善身体机能，提升身心健康水平。 六、术后康复专项调理 专注各类手术术后中医固本康复调治，涵盖肿瘤、骨科、妇科、普外等术后人群。术后机体多因创伤耗损元气、脏腑受损、经络瘀堵、邪毒残留，致使体质虚弱、创面愈合迟缓、肢体僵硬肿痛、周身困顿乏力、抗病能力薄弱，易出现恢复缓慢、局部粘连、后遗不适反复发作等状况。临证秉持固本复元、益气健脾、养血和络、散瘀消肿、清余邪、调阴阳的施治原则，依据不同手术类型、术后恢复阶段及个人体质精准辨证配药，助力修复机体创伤、疏通阻滞经络，快速改善术后虚弱状态，提升机体抵御外邪能力，规避术后并发症与复发风险，高效推动全身脏腑机能与体质稳步复原。"
  },
