  "52110": {
    "bio": [
      "贵州籍，医学硕士，毕业首都医科大学。在首都医科大学附属北京安贞医院完成住院医师规范化培训，在北京大学国际医院泌尿外科历经住院医师及住院总医师，并成功通过北京大学医学部专科医师二阶段培训考核，现担任北京大学国际医院泌尿外科主治医师。参与完成北京市自然科学基金课题在内的多项科研课题，并在国内外核心期刊上发表肾癌及前列腺癌相关的多篇研究论文及文献综述。"
    ],
    "appointments": [],
    "honors": [
      "2025“金石唯开”病例分享大赛北部赛区二等奖"
    ],
    "specialty": "泌尿系结石及肿瘤腔内治疗，前列腺及肾上腺疾病微创治疗，男性生殖系常见疾病手术治疗如包皮环切，精索静脉高位结扎及鞘膜积液切除等。 对于泌尿外科各种常见疾病，如泌尿系结石及肿瘤、前列腺增生、肾上腺疾病的诊断和治疗具有较为丰富的经验，年均管理各类疾病患者 500余人。此外，专注于开展各类泌尿外科微创手术技术，如经尿道输尿管镜碎石、经尿道膀胱肿瘤/前列腺电切、腹腔镜精索筋脉高位结扎/肾囊肿去顶/肾上腺肿瘤切除术等，已独立完成一定数量的相关手术，均取得了理想的治疗效果。"
  },
  "972": {
    "bio": [
      "皮肤美容主诊医师，皮肤性病学硕士，历经系统化皮肤科与皮肤美容专科训练，构建了扎实的皮肤解剖、病理生理及疾病诊疗理论体系。从事皮肤美容临床工作十余年，深耕激光光电、注射美容与损容性皮肤病诊疗领域，专注色素性病变、医美术后皮肤屏障受损及色素异常、痤疮及玫瑰痤疮、不同肤质的维养抗衰、注射美学以及面部年轻化综合治疗，诊疗风格兼顾医学严谨性与个性化需求。",
      "从业以来持续精进技术，曾赴多家顶尖医疗机构、学术会议交流学习，系统研习激光光电设备精准操作、注射美容层次把控及皮肤屏障修复技术，将国内外先进理念与临床实践深度融合。临床中坚持从皮肤的病理生理以及皮肤与机体整体之间的关系出发，以解决问题、维护健康为前提设计方案。经过长期临床沉淀，形成“疾病诊疗与美容需求双向协同”的专属技术体系。将色斑、瘢痕、痤疮等损容性疾病治疗中积累的皮肤病理生理认知、组织修复经验，灵活应用于激光祛斑、注射填充、抗衰嫩肤等项目。"
    ],
    "appointments": [
      "中国整形美容协会微创与皮肤整形美容分会 委员",
      "中国整形美容协会青年医师交流部 委员",
      "入选2026年北京市全国西医学习中医骨干人才培训项目",
      "“2025年润致百分医生案例大赛”北大区美塑赛场 “冠军”",
      "瑞蓝智臻“领航大师”；“塑颜萃”、“热玛吉”等官方认证医师。",
      "发表SCI及核心期刊文章数篇；参与翻译著作2部；多次大会发言。",
      "论文发表：",
      "1. Yang Yi, Lin Jingrong, Fang Shifeng, Han Shixin, Song Zhiqi; What's new in dermoscopy of Bowen's disease: two new dermoscopic signs and its differential diagnosis; International Journal of Dermatology. 2017 Oct;56(10):1022-1025.",
      "2. 杨易,张芊,张雅芝,等.手足皮肤反应与手足综合征[J].临床皮肤科杂志,2023,52(02):125-128.",
      "3. Yang Y, Zhao Z, Lu L, Gao N, Hu J, Han G, Ma X. Tape-Strip Proteomic Analysis of Female Melasma Skin Lesions in a Chinese Population. Clin Cosmet Investig Dermatol. 2025 Sep 12;18:2341-2357.",
      "4. Yang Y, Zhao Z, Lu L, Gao N, Hu J, Zhang X, Han G, Ma X. Lipidomic profiling of skin surface lipids in a cohort of Chinese patients with rosacea. Sci Rep. 2025 Nov 7;15(1):39163."
    ],
    "honors": [
      "“2025年润致百分医生案例大赛”北大区美塑赛场 “冠军”",
      "2022年度北京大学国际医院“优秀员工"
    ],
    "specialty": "皮肤美容主诊医师 1.专注各类色斑、痤疮、玫瑰痤疮、面部潮红、皮肤肿物（痣、疣、囊肿、血管瘤等）、瘢痕等损容性皮肤病的分层与联合诊疗；尤其对医美术后皮肤屏障受损/色素异常、黄褐斑、雀斑、褐青色痣等复合型色斑、以及难治性痤疮有丰富的诊疗经验；2.精准分析不同肤质的健康维护及美容抗衰：对于敏感肌、油痘肌、干燥肌等皮肤问题治疗、预防维护；3.面部年轻化综合方案设计，尤其擅长眼周、口周以及下面部松垂的非手术抗衰治疗，注重个体化定制光电、注射整合方案，在医疗基础上坚持守护“本我风格”；4.熟练各种光电（光子嫩肤、皮秒、热玛吉、超声炮、黄金微针、点阵激光等）、注射（玻尿酸、胶原蛋白、童颜水光/面部凹陷填充/颈纹填充/轮廓提升塑形等；肉毒素除皱、提升、瘦肩、瘦腿等）治疗。"
  },
