    "specialty": "肝癌、肺癌、宫颈癌及消化道等肿瘤的血管介入治疗及射频、微波、冷冻、纳米刀等消融治疗；大咯血的栓塞治疗；消化道出血介入治疗、TIPS；梗阻性黄疸的介入治疗（引流、活检及放射性粒子支架植入）；静脉港；CT 引导下肺、肝及其他组织活检、放射性粒子植入；静脉滤器、血栓抽吸；肺动脉狭窄、肺栓塞的介入治疗；气管、食道及肠道支架植入等。"
