  "969": {
    "bio": [
      "王成源，主治医师，美容外科主诊医师。毕业于北京协和医学院--中国医学科学院整形外科医院（八大处整形医院）整形外科专业，后在301医院、北京大学第三医院学习，目前就职于北京大学国际医院医学美容科、整形外科。自2012年从事整形美容行业，专注于面部微创整形美容的手术与非手术治疗，尤其在眼部整形领域有较多研究。目前已在国内核心期刊发表学术文章8篇，参编参译专业书籍3本，多次参加国内整形美容会议并作会议发言。"
    ],
    "appointments": [
      "社会任职：",
      "中国整形美容协会超显微医学修复分会 理事",
      "中国面部整形与重建外科学会眼整形专业委员会 委员",
      "全球（泛亚）医美与大健康产业大会暨中国医美创新发展大会眼整形专业学术委员会 委员",
      "学术文章：",
      "1. 王成源, 朱晓峰等. 显微技术辅助皮下内固定法在重睑成形术中的应用. 中华临床医师杂志，2020（8）.",
      "2. 王成源. 注射用修饰透明质酸钠凝胶用于唇部填充安全性和有效性的前瞻性临床研究. 全国微创医学美容大会. 2022.",
      "3. 甄永环, 王成源, 安阳等. 睑结膜入路去睑袋辅助纳米脂肪填充在眶周年轻化中的应用. 中国美容整形外科杂志 ( 2021 )",
      "4. 王成源, 杨明勇, 李东. 内眦赘皮的临床治疗进展. 中国美容整形外科杂志, 2018(5)",
      "5. 王成源, 吕唯, 庄岩,等. 中国人对内眦赘皮的美学认知调查. 中国美容整形外科杂志, 2015, 26(7):407-410.",
      "6. 王成源. 中国人对内眦赘皮的美学认知调查[D]. 北京协和医学院中国医学科学院;北京协和医学院;中国医学科学院;清华大学医学部, 2015.",
      "7. 王成源.30 岁以下年轻女性的去皮重睑术探讨. //2015 中华医学会整形外科学分会第十四次全国学术交流会暨第五届中国(福州)ISAPS 美容整形外科高级研讨会论文集.",
      "8. 王成源, 杨明勇. 阴茎再造感觉功能重建的研究现状. 中国美容整形外科杂志, 2015, 26(1):54-56.",
      "9. 王成源, 刘越, 李斌斌等. A 型肉毒毒素治疗面部皱纹效果观察. 中国美容医学杂志, 2013, 22(10):1026-1029."
    ],
    "honors": [
      "北京大学国际医院 2019 年度优秀员工"
    ],
    "specialty": "1. 眼部整形：定制个性化的双眼皮，失败双眼皮修复，开内眼角，内眼角修复，上睑下垂矫正，提眉、去眼袋等各类眼周年轻化抗衰项目。 2. 轻医美：肉毒素、玻尿酸、胶原蛋白、童颜针等注射美容；水光、中胚层美塑、微针等皮肤抗衰治疗。光子嫩肤、皮秒激光改善雀斑、黄褐斑、晒斑、真皮斑等各类色素问题、泛红与肤色暗沉；热玛吉、热拉提、超声刀、钻石电波等面部紧致抗衰项目；点阵激光、离子束、微针修复痘坑、痘印等痤疮疤痕；激光脱毛等。 3. 美容外科手术：美容精细化切除色素痣、囊肿等皮肤肿物；违规 / 异常注射物微创取出；微创腋臭（狐臭）根治术；面部吸脂、全脸自体脂肪填充抗衰；全身吸脂塑形、自体脂肪丰胸；各类疤痕精细化综合修复。"
  },
