  "1157": {
    "bio": [
      "博士，主治医师，2015年毕业于北京大学医学部，于核心期刊发表学术论文，目前主要研究方向为关节疾病的诊断及治疗、3D打印个体化人工关节置换、智能医疗。"
    ],
    "appointments": [
      "中国微循环学会转化医学专业委员会委员",
      "中国微循环学会转化医学专业委员会骨科学组委员"
    ],
    "honors": [],
    "specialty": "骨科疾病的诊治，尤其是关节疾病和运动医学方向疾病的诊治。擅长膝、髋、踝、肩、肘、腕等关节的疼痛、关节炎、运动损伤、骨坏死等的诊疗，擅长人工髋、膝关节置换术（如骨关节炎、股骨头坏死、股骨颈骨折、类风湿关节炎等）和微创关节镜手术（如关节内游离体、膝关节半月板损伤、交叉韧带等韧带损伤、髌骨脱位、骨坏死、髋臼盂唇损伤、踝扭伤踝关节韧带损伤、冻结肩、肩袖损伤、腕肘关节损伤等）、四肢骨折内固定手术。以及骨科常见疾病如颈肩痛、腰腿痛、四肢骨折创伤等疾病的诊治。"
  },
