    "specialty": "高血压、糖尿病、高脂血症、动脉粥样硬化、冠心病、心力衰竭、骨质疏松等的诊治及长期管理，代谢综合征（肥胖、高血糖、血脂异常、高尿酸血症、高血压、胰岛素抵抗等）的综合管理；呼吸系统、心血管系统、消化系统等常见病及多发病的诊疗；内科未分化疾病的诊断；常见体检异常情况解读；成人疫苗接种前评估及制定免疫接种计划。"
