    "specialty": "下肢静脉曲张个体化极微创治疗，参与完成数百例 “保留”静脉的手术， 在国内较早开展此项术式，摒弃了传统射频的“破坏”性理念，创伤小，恢复快，无需住院，形成了我院独具特色的静脉曲张诊疗体系（CHIVA-血流动力学纠正术）。 全身血管造影及腔内血管的介入治疗，包括：外周动脉粥样硬化性狭窄（如：锁骨下动脉、肾动脉、髂股动脉等）、下肢深静脉血栓形成、髂静脉压迫综合征等常见动静脉类疾病。"
