  "52113": {
    "bio": [
      "北京大学国际医院药剂科主任、主任药师，硕士生导师。主要从事临床药学的教学与实践以及临床药理学研究。在临床实践及教学工作中侧重于治疗药物监测及特殊人群用药指导。已培养硕士生10名。作为第一作者或通讯作者发表SCI及统计源期刊文章百余篇，参编著作多部，承担2部译著的主译工作。多次在国际会议上进行大会或分会场发言。曾获北京药学会优秀药师奖，优秀论文奖，北京大学医学部优秀教师奖、教学比赛优秀奖。"
    ],
    "appointments": [
      "北京药学会智慧药学和智能化管理专业委员会副主任委员；北京药师协会非公医院药事管理专业委员会副主任委员；北京药师协会治疗药物监测药师分会常务委员；中国医学装备协会药学装备分会常务委员；中国医药新闻信息协会儿童安全用药分会常委；《中国新药杂志》《中国药房》、《临床药物治疗杂志》、《中国医院用药评价与分析》杂志和《药品评价》杂志编委。"
    ],
    "honors": [],
    "specialty": "擅长体内药物分析及药代动力学研究，作为主要研究者完成多项国内、外新药的Ⅰ期临床试验，以及药动学和生物等效性研究。在临床实践及教学工作中侧重于治疗药物监测及特殊人群用药指导。"
  },
  "97812": {
    "bio": [
      "沈姝玥，毕业于北京中医药大学中医学（卓越针推5+3），师承首都名中医、岐黄学者张学智教授。擅长以中医整体观为指导，形成“病证结合、针药并用”的诊疗体系，诊疗中注重整体调和、标本兼治，力求在控制病情的同时提升患者整体生命质量。"
    ],
    "appointments": [
      "参与国家自然科学基金、首都卫生发展科研项目等科研课题6项；发表论文10余篇；参与书籍编写5部。"
    ],
    "honors": [],
    "specialty": "1、消化系统疾病（胃食管反流、慢性胃炎、功能性便秘）的中医辨证调治；2、针药结合治疗失眠、头晕头痛、耳鸣及颈腰椎病、肩周炎等疼痛类疾病；3、四肢麻木、凉痛等周围神经血管疾病；4、脑梗后遗症的康复治疗；5、亚健康状态（疲乏、体虚、情绪失调）的中医整体调理。"
  },
