      "具有国家执业药师、中级药师、医院规培药师、临床药师、药物治疗管理药师资质。药学硕士研究生，先后在北医系统经历了三年住院药师培训，一年抗凝治疗专业临床药师培训，中国药物治疗管理（CMTM）培训。目前从事临床药学工作，在临床合理用药方面积累了许多宝贵经验，能根据患者的病理生理特点有针对性的给予患者用药建议，避免或减少药物不良反应的发生，提高用药安全性和有效性。"
