  "1355": {
    "bio": [
      "​贾立华，",
      "主任药师 临床药师带教师资",
      "药剂科主任 临床试验机构副主任"
    ],
    "appointments": [
      "中国药理学会治疗药物监测研究专业委员会委员",
      "北京药学会抗感染专业委员会委员",
      "北京中西医结合学会专业委员会常务委员",
      "北京中医药学会临床药学专业委员会委员",
      "北京市昌平区药学质控中心主任委员",
      "主持多项军队和地方课题，发表学术论文40余篇，主编专著2部。担任《中国药物应用与监测》、《解放军药学学报》和《中国临床药学杂志》审稿专家。"
    ],
    "honors": [],
    "specialty": "主要从事药事管理和临床药学服务工作。擅长感染性疾病的评估和会诊、心血管和内分泌等常见代谢性疾病的药物治疗管理、个体化用药监测、药物不良反应识别、药品综合评价、患者用药教育等工作。"
  },
  "1353": {
    "bio": [
      "美国药物治疗管理（MTM）糖尿病专科药师、神经内科临床药师、执业药师。2014年毕业于北京大学医学部，药学硕士研究生。2014年-2016年完成北京市医院药师规范化培训。2017年完成卫生部神经内科临床药师培训。2018年完成美国MTM糖尿病专科药师培训项目并获得证书。以第一作者发表SCI论文1篇。"
    ],
    "appointments": [],
    "honors": [
      "第七届中国药师职业技能大赛省级赛区二等奖"
    ],
    "specialty": "美国药物治疗管理（MTM）糖尿病专科药师、神经内科临床药师，擅长糖尿病、心脑血管等疾病常用药物的个性化用药评估，合并多种用药的药物重整、药物不良反应鉴别和防范、药物治疗的全程化管理。"
  },
